def maximumScoreAfterOperations(edges, values):
    n = len(values)
    tree = [[] for _ in range(n)]
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    # BFS order from the root, then process children before parents
    parent = [-1] * n
    order = [0]
    for node in order:
        for child in tree[node]:
            if child != parent[node]:
                parent[child] = node
                order.append(child)

    # keep[u] = minimum total value we must leave untouched in u's subtree
    # so that every root-to-leaf path in the subtree has a nonzero node
    keep = [0] * n
    for node in reversed(order):
        child_keep = 0
        is_leaf = True
        for child in tree[node]:
            if child != parent[node]:
                is_leaf = False
                child_keep += keep[child]
        if is_leaf:
            keep[node] = values[node]           # leaf must keep its own value
        else:
            keep[node] = min(values[node], child_keep)

    return sum(values) - keep[0]
